-- Demo journal articles
insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category_id, author_name, author_bio, status, published_at, reading_minutes, is_demo)
values ('How Many Yards Do You Really Need? A Lace Buying Guide', 'how-many-yards-do-you-really-need-a-lace-buying-guide', 'From mermaid gowns to iro and buba, here is how to estimate yardage before you buy.', 'Buying the right amount of fabric saves money and avoids the stress of trying to match a second bolt later. Use this guide as a starting point, then confirm with your designer.

## Typical yardage by style

| Style | Approximate yardage |
| --- | --- |
| Fitted mermaid gown | 4–5 yards |
| Iro and buba | 5 yards |
| Ball gown with train | 7–10 yards |
| Men''s agbada (3-piece) | 10 yards |
| Kaftan or senator | 4–5 yards |

## Why bundles matter

Many of our luxury laces are sold as **four- or five-yard bundles** cut from a single bolt. This guarantees consistent colour and embellishment density across your whole outfit.

## Tips before you buy

- Share your style inspiration with your designer first.
- Add half a yard for pattern matching on large motifs.
- For Asoebi groups, order from one dye lot — ask us to reserve stock.', '/demo/journal-how-many-yards-do-you-really-need-a-lace-buying-guide.svg', (select id from public.blog_categories where slug = 'fabric-guides'),
  'Lobaloba Editorial', 'Fabric specialists and stylists at Lobaloba Deluxe.', 'published', now() - interval '1 days', 1, true);
insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category_id, author_name, author_bio, status, published_at, reading_minutes, is_demo)
values ('Planning Asoebi for 200 Guests Without the Stress', 'planning-asoebi-for-200-guests-without-the-stress', 'A timeline and checklist for coordinators managing large Asoebi groups.', 'Coordinating Asoebi for a large celebration is a project in its own right. Here is the timeline we recommend to couples and coordinators.

## 12 weeks before

- Choose your colour story and fabric shortlist.
- Request a quotation with your estimated guest count.

## 10 weeks before

- Confirm fabric and reserve stock from a single dye lot.
- Share your event page link with guests so each person can pay individually.

## 6 weeks before

- Close orders and confirm final quantities.
- Arrange delivery — individual or collective.

## Why use an event page?

An event page lets every guest select, pay and track their own Asoebi, while you monitor paid and unpaid orders in one place.', '/demo/journal-planning-asoebi-for-200-guests-without-the-stress.svg', (select id from public.blog_categories where slug = 'asoebi-planning'),
  'Lobaloba Editorial', 'Fabric specialists and stylists at Lobaloba Deluxe.', 'published', now() - interval '7 days', 1, true);
insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category_id, author_name, author_bio, status, published_at, reading_minutes, is_demo)
values ('Caring for Beaded and Crystal Fabrics', 'caring-for-beaded-and-crystal-fabrics', 'Keep your embellished fabrics sparkling for years with these simple care rules.', 'Embellished fabrics are investments. A little care keeps them looking new.

## Storage

- Store flat or rolled around a tube — never folded sharply.
- Wrap in acid-free tissue and keep away from direct sunlight.

## Cleaning

- **Dry clean only** with a cleaner experienced in embellished garments.
- Never wring, twist or tumble dry.

## Pressing

Press from the reverse side on a low setting with a pressing cloth, avoiding direct heat on beads and crystals.', '/demo/journal-caring-for-beaded-and-crystal-fabrics.svg', (select id from public.blog_categories where slug = 'fabric-care'),
  'Lobaloba Editorial', 'Fabric specialists and stylists at Lobaloba Deluxe.', 'published', now() - interval '13 days', 1, true);
insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category_id, author_name, author_bio, status, published_at, reading_minutes, is_demo)
values ('Five Bridal Lace Looks for the Modern Nigerian Bride', 'five-bridal-lace-looks-for-the-modern-nigerian-bride', 'From illusion sleeves to sculpted corsetry — bridal looks we love this season.', 'Bridal lace is endlessly versatile. These are the looks our brides are loving.

1. **Illusion sleeves** in Chantilly-style lace.
2. **Corseted bodices** in structured duchess satin with lace appliqué.
3. **Cathedral trains** edged with scalloped eyelash lace.
4. **Second-look mini dresses** in pearl-beaded tulle.
5. **Traditional reception** looks in stone-encrusted lace with coral beads.

Visit our Bridal Edit to explore fabrics for each look.', '/demo/journal-five-bridal-lace-looks-for-the-modern-nigerian-bride.svg', (select id from public.blog_categories where slug = 'bridal-inspiration'),
  'Lobaloba Editorial', 'Fabric specialists and stylists at Lobaloba Deluxe.', 'published', now() - interval '19 days', 1, true);

